ins:
.metric-x-row { display: flex; gap: var(--s-out); margin-top: var(--s-out); }
.metric-x { /* @critical */ flex: 1; border-top: 1px solid var(--hairline); padding-top: 18px; }
.metric-x .mv { font-family: var(--font-serif); font-size: var(--fs-num); font-weight: 600; font-variant-numeric: tabular-nums; }
.metric-x .mv small { font-size: 0.4em; font-weight: 400; color: var(--ink-dim); }
.metric-x .ml { font-size: var(--fs-body); margin-top: 16px; }
.metric-x .md { font-size: var(--fs-body); color: var(--ink-dim); margin-top: var(--s-in); line-height: 1.5; }
